    #[test]
    fn test_perlin_noise() {
        run_test(
            &TEST,
            |rand, (first_octave, amplitudes)| PerlinNoise::new(rand, *first_octave, amplitudes),
            PerlinNoise::noise,
        );
    }

    #[test]
    fn test_legacy_perlin_noise() {
        run_test(
            &LEGACY_TEST,
            |rand, octaves| PerlinNoise::new_legacy(rand, &(octaves.clone().into_iter().collect::<Vec<_>>())),
            PerlinNoise::noise,
        )
    }
